@keyframes đếm ngược {
 0% {
 biến đổi: tỷ lệ (0,5);
 độ mờ: 0;
 }
 20% {
 biến đổi: tỷ lệ (1.2);
 độ mờ: 1;
 }
 40% {
 biến đổi: tỷ lệ (1);
 }
 100% {
 biến đổi: tỷ lệ (0,8);
 độ mờ: 0;
 }
 }

 @keyframes mờ dần {
 từ {
 độ mờ: 0;
 biến đổi: dịchY(20px);
 }
 đến {
 độ mờ: 1;
 biến đổi: dịchY(0);
 }
 }

 .animate-đếm ngược {
 hoạt hình: đếm ngược 1 giây dễ dàng chuyển tiếp;
 }

 .animate-fade-in {
 hoạt hình: giảm dần 0,5 giây dễ dàng chuyển tiếp;
 }
